import{bV as a,aL as i,u as e,G as n}from"./chunks/framework.O9JQzcbi.js";const k=JSON.parse('{"title":"排查笔记：a-config-provider 配了中文，DatePicker 面板却还是英文？","description":"","frontmatter":{"title":"排查笔记：a-config-provider 配了中文，DatePicker 面板却还是英文？","date":"2026-08-28T00:00:00.000Z","categories":["Vue"],"tags":["dayjs","ant-design-vue","pnpm","排查"]},"headers":[],"relativePath":"log/vue/antd-datepicker-dayjs-duplicate-instance.md","filePath":"log/vue/antd-datepicker-dayjs-duplicate-instance.md","lastUpdated":1789838113000}'),t={name:"log/vue/antd-datepicker-dayjs-duplicate-instance.md"};function p(l,s,d,o,h,c){return i(),e("div",null,[...s[0]||(s[0]=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /log/vue/antd-datepicker-dayjs-duplicate-instance.md for this page in Markdown format</div><h1 id="排查笔记-a-config-provider-配了中文-datepicker-面板却还是英文" tabindex="-1">排查笔记：a-config-provider 配了中文，DatePicker 面板却还是英文？ <a class="header-anchor" href="#排查笔记-a-config-provider-配了中文-datepicker-面板却还是英文" aria-label="Permalink to &quot;排查笔记：a-config-provider 配了中文，DatePicker 面板却还是英文？&quot;">​</a></h1><blockquote><p>一个典型的「配置生效了，但又没完全生效」的 case，根因藏在 pnpm 依赖结构里。</p></blockquote><h2 id="问题现象" tabindex="-1">问题现象 <a class="header-anchor" href="#问题现象" aria-label="Permalink to &quot;问题现象&quot;">​</a></h2><p>在 Vue 3 + ant-design-vue 4 项目中，<code>App.vue</code> 里明明做了三件套配置：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;dayjs/locale/zh-cn&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 注册中文 locale</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> zhCN </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ant-design-vue/es/locale/zh_CN&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 引入中文语言包</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dayjs.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">locale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;zh-cn&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 设置 dayjs 全局语言</span></span></code></pre></div><p>模板里也包了 <code>&lt;a-config-provider :locale=&quot;zhCN&quot;&gt;</code>。然而打开页面：</p><ul><li>日期选择器的<strong>输入框占位符是中文</strong>（&quot;请选择日期&quot;）</li><li>但<strong>弹出面板里的月份、星期全是英文</strong>（Jan / Feb / Sun / Mon…）</li></ul><p>语言包似乎生效了，又似乎没生效，非常割裂。</p><h2 id="排查思路" tabindex="-1">排查思路 <a class="header-anchor" href="#排查思路" aria-label="Permalink to &quot;排查思路&quot;">​</a></h2><h3 id="_1-先确认-antd-语言包有没有生效" tabindex="-1">1. 先确认 antd 语言包有没有生效 <a class="header-anchor" href="#_1-先确认-antd-语言包有没有生效" aria-label="Permalink to &quot;1. 先确认 antd 语言包有没有生效&quot;">​</a></h3><p>占位符是中文，说明 <code>ConfigProvider</code> 的 <code>zh_CN</code> 语言包<strong>生效了</strong>。占位符文本来自 antd 的语言包对象（<code>DatePicker.lang.placeholder</code>），与 dayjs 无关。</p><h3 id="_2-面板的月份-星期文案来自哪里" tabindex="-1">2. 面板的月份/星期文案来自哪里？ <a class="header-anchor" href="#_2-面板的月份-星期文案来自哪里" aria-label="Permalink to &quot;2. 面板的月份/星期文案来自哪里？&quot;">​</a></h3><p>这是关键。打开 ant-design-vue 的 <code>vc-picker</code> 源码，日期面板渲染月份、星期用的是：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// vc-picker/panels/DatePanel/DateBody.js</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> weekDaysLocale</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> locale.shortWeekDays </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> generateConfig.locale.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getShortWeekDays</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(locale.locale)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// vc-picker/generate/dayjs.js</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getShortMonths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">locale</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> dayjs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">locale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">parseLocale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(locale)).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">localeData</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">monthsShort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>也就是说，<strong>面板文案直接取自 dayjs 的 localeData</strong>。所以就算 antd 语言包是中文，只要 <strong>dayjs 实例里没注册 <code>zh-cn</code></strong>，面板照样渲染英文。</p><h3 id="_3-那-dayjs-的-zh-cn-到底注册了没有" tabindex="-1">3. 那 dayjs 的 <code>zh-cn</code> 到底注册了没有？ <a class="header-anchor" href="#_3-那-dayjs-的-zh-cn-到底注册了没有" aria-label="Permalink to &quot;3. 那 dayjs 的 \`zh-cn\` 到底注册了没有？&quot;">​</a></h3><p>写脚本验证，结果让人意外：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>== 应用里的 dayjs ==</span></span>
<span class="line"><span>active locale: zh-cn  ✅</span></span>
<span class="line"><span>monthsShort: [&quot;1月&quot;,&quot;2月&quot;,&quot;3月&quot;]  ✅</span></span>
<span class="line"><span></span></span>
<span class="line"><span>== ant-design-vue 内部的 dayjs ==</span></span>
<span class="line"><span>active locale: en  ❌</span></span></code></pre></div><p><strong>同一个进程里出现了两个 dayjs 实例！</strong> App.vue 里注册的 <code>zh-cn</code> 只作用在「应用那份」dayjs 上，而 antd 渲染面板用的是「另一份」完全独立的 dayjs。</p><h2 id="根因-dayjs-被安装了两次" tabindex="-1">根因：dayjs 被安装了两次 <a class="header-anchor" href="#根因-dayjs-被安装了两次" aria-label="Permalink to &quot;根因：dayjs 被安装了两次&quot;">​</a></h2><p>dayjs 是<strong>单例设计</strong>的 —— locale、插件都挂在模块级变量上。一旦项目里存在两份 dayjs，就会各持一份&quot;独立世界&quot;。</p><p>看 pnpm 依赖结构就明白了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node_modules/dayjs                                        → 1.11.23（应用用）</span></span>
<span class="line"><span>node_modules/.pnpm/ant-design-vue@4.2.6_.../node_modules/dayjs → 1.11.20（antd 用）</span></span></code></pre></div><ul><li>应用声明 <code>&quot;dayjs&quot;: &quot;^1.11.23&quot;</code>，被 hoist 到顶层</li><li>ant-design-vue 声明 <code>&quot;dayjs&quot;: &quot;^1.10.5&quot;</code>，pnpm 在生成 lockfile 时给它解析到了 <strong>1.11.20</strong>，作为嵌套依赖安装</li></ul><p>于是 antd 的 <code>vc-picker/generate/dayjs.js</code> 里那句 <code>import dayjs from &#39;dayjs&#39;</code>，按 Node 解析规则优先命中它自己嵌套的那份 <strong>1.11.20</strong> —— 这份实例里 <code>zh-cn</code> 从未被注册过，默认英文。</p><p>用 <code>require.resolve</code> 可以实锤：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 从 antd 的 generate 目录解析 dayjs</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">req.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resolve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;dayjs&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// → .../.pnpm/dayjs@1.11.23/node_modules/dayjs/dayjs.min.js（修复前是 1.11.20）</span></span></code></pre></div><h2 id="修复-让所有-dayjs-统一到同一个版本" tabindex="-1">修复：让所有 dayjs 统一到同一个版本 <a class="header-anchor" href="#修复-让所有-dayjs-统一到同一个版本" aria-label="Permalink to &quot;修复：让所有 dayjs 统一到同一个版本&quot;">​</a></h2><p>核心思路是<strong>消除重复实例</strong>，而不是到处补注册。用 pnpm overrides 强制所有依赖统一使用根项目的 dayjs 版本。</p><p>配置写在 <code>pnpm-workspace.yaml</code>（项目根，monorepo 推荐位置）：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># pnpm-workspace.yaml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">overrides</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  dayjs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">^1.11.23</span></span></code></pre></div><p>也可以写 <code>$dayjs</code> —— 表示&quot;取根项目 package.json 里 dayjs 声明的版本&quot;（pnpm 10/11 支持，锁文件会解析成具体版本）：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">overrides</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  dayjs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$dayjs</span></span></code></pre></div><p>然后重新安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>这样 antd 和应用的 dayjs 会合并为同一个 hoisted 实例，<code>pnpm-lock.yaml</code> 头部也会记录这份 overrides。</p><p>修复后验证：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>是否同一实例: true</span></span>
<span class="line"><span>antd dayjs active locale: zh-cn</span></span>
<span class="line"><span>monthsShort: [&quot;1月&quot;,&quot;2月&quot;,&quot;3月&quot;]</span></span></code></pre></div><p>日期面板终于全中文了。</p><h2 id="经验总结" tabindex="-1">经验总结 <a class="header-anchor" href="#经验总结" aria-label="Permalink to &quot;经验总结&quot;">​</a></h2><ol><li><p><strong>单例模块被重复安装，是最隐蔽的坑之一。</strong> dayjs、moment、<code>lodash</code> 这类模块级状态的库，重复实例化会导致&quot;配置了但没生效&quot;。同类问题还包括 UI 库与业务各自持有不同实例导致的 <code>useContext</code>/注入失效等。</p></li><li><p><strong>先分清&quot;配置生效的对象&quot;和&quot;实际渲染的对象&quot;。</strong> 占位符中文、面板英文，说明语言来源有两个（antd 语言包 vs dayjs locale），按渲染链路逐个确认，就能快速锁定。</p></li><li><p><strong>验证依赖解析用 <code>require.resolve</code>。</strong> 不要猜，直接看模块最终解析到哪个文件、哪个版本，一切一目了然。</p></li><li><p><strong>pnpm overrides 是治理这类问题的通用手段。</strong> 可写在 <code>pnpm-workspace.yaml</code>（推荐）或 <code>package.json</code> 的 <code>pnpm.overrides</code>，直接指定版本即可。若用 <code>$</code> 跟随根版本，注意 pnpm 12（pacquet 重写版）曾存在不解析 <code>$</code> 自引用的 bug，升级时留意；官方更推荐用 catalog 机制统一维护版本。</p></li></ol>`,42)])])}const g=a(t,[["render",p]]);export{k as __pageData,g as default};
